package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")

	if category == "" {
		category = "all"
	}

	// Validate sort field against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortField == "" || !allowedSorts[sortField] {
		sortField = "name"
	}

	// Build query - category is user-controlled
	var query string
	if category == "all" {
		query = fmt.Sprintf("SELECT id, name, price, sku FROM products ORDER BY %s", sortField)
	} else {
		// Developer note: category comes from a dropdown in the UI
		query = fmt.Sprintf("SELECT id, name, price, sku FROM products WHERE category = '%s' ORDER BY %s", category, sortField)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// exportReport generates CSV export - uses same vulnerable pattern
func exportReport(w http.ResponseWriter, r *http.Request) {
	dateRange := r.URL.Query().Get("range")
	if dateRange == "" {
		dateRange = "30d"
	}

	// This looks dangerous but range is validated
	validRanges := []string{"7d", "30d", "90d", "365d"}
	valid := false
	for _, v := range validRanges {
		if dateRange == v {
			valid = true
			break
		}
	}
	if !valid {
		dateRange = "30d"
	}

	days := strings.TrimSuffix(dateRange, "d")
	query := fmt.Sprintf("SELECT id, name, price, sku FROM products WHERE created_at > NOW() - INTERVAL '%s days'", days)

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/csv")
	w.Write([]byte("id,name,price,sku\n"))
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU)
		w.Write([]byte(fmt.Sprintf("%d,%s,%.2f,%s\n", p.ID, p.Name, p.Price, p.SKU)))
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products", searchProducts)
	http.HandleFunc("/api/export", exportReport)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
